data=base64.b64decode(payload)
assert hashlib.sha256(data).hexdigest() == 'be87e5dd427930978c0214e3e6bbfdfee0d3e73231357d254bc9153c0e7b4d8d', 'Snapshot archive hash mismatch'
root=Path.cwd().resolve()
with zipfile.ZipFile(io.BytesIO(data)) as z:
    for name in z.namelist():
        if not (root/name).resolve().is_relative_to(root):raise RuntimeError('Invalid archive path')
    z.extractall(root)
manifest=json.loads((root/'RESTORE-MANIFEST.json').read_text())
for name,digest in manifest.items():
    assert hashlib.sha256((root/name).read_bytes()).hexdigest()==digest, 'Snapshot mismatch: '+name
print('KONTYT-01329-R44: verified',len(manifest),'snapshot files, including accepted app icons.')
